function e(?string $s): string { return htmlspecialchars($s ?? '', ENT_QUOTES, 'UTF-8'); }
function taskScope(array $me, string $role): array {
    if (in_array($role, ['ADMIN','DIRECTOR'], true)) return ['', []];
    if ($role === 'SUPERVISOR') return ['(t.assigned_department_id = ? OR creator.department_id = ?)', [$me['department_id'], $me['department_id']]];
    return ['(t.created_by = ? OR t.assigned_to = ?)', [$me['user_id'], $me['user_id']]];
}
function canEditTask(array $task, array $me, string $role): bool {
    if (in_array($role, ['ADMIN','DIRECTOR'], true)) return true;
    if ($role === 'SUPERVISOR') return (int)$task['assigned_department_id'] === (int)$me['department_id'] || (int)$task['creator_department_id'] === (int)$me['department_id'];
    return (int)$task['created_by'] === (int)$me['user_id'] || (int)$task['assigned_to'] === (int)$me['user_id'];
}
function storeNotification(PDO $pdo, int $userId, ?int $actorId, ?int $taskId, string $title, string $message, string $link): void {
    try { $stmt=$pdo->prepare('INSERT INTO notifications(user_id,actor_user_id,task_id,title,message,link) VALUES(?,?,?,?,?,?)');$stmt->execute([$userId,$actorId,$taskId,$title,$message,$link]); }
    catch(PDOException $exception){ error_log('Notification could not be stored: '.$exception->getMessage()); }
}
function saveEvidenceUpload(array $file): ?string {
    if (($file['error'] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) return null;
    if (($file['error'] ?? UPLOAD_ERR_OK) !== UPLOAD_ERR_OK || !is_uploaded_file($file['tmp_name'] ?? '')) throw new RuntimeException('อัปโหลดไฟล์ไม่สำเร็จ');
    if ((int)($file['size'] ?? 0) > 10 * 1024 * 1024) throw new RuntimeException('ไฟล์แนบต้องมีขนาดไม่เกิน 10 MB');
    $mime = (new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);
    $extensions = ['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','application/msword'=>'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','application/vnd.ms-excel'=>'xls','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'=>'xlsx'];
    if (!isset($extensions[$mime])) throw new RuntimeException('ชนิดไฟล์ไม่รองรับ กรุณาแนบ PDF, รูปภาพ, Word หรือ Excel');
    $directory = __DIR__ . '/uploads/evidence';
    if (!is_dir($directory) && !mkdir($directory, 0750, true) && !is_dir($directory)) throw new RuntimeException('ไม่สามารถเตรียมพื้นที่เก็บไฟล์แนบได้');
    $relative = 'uploads/evidence/' . bin2hex(random_bytes(20)) . '.' . $extensions[$mime];
    if (!move_uploaded_file($file['tmp_name'], __DIR__ . '/' . $relative)) throw new RuntimeException('จัดเก็บไฟล์แนบไม่สำเร็จ');
    return $relative;
}

