        $users=$pdo->query($sql.' ORDER BY u.full_name')->fetchAll();
    }
    try{$notificationStmt=$pdo->prepare('SELECT notification_id,title,message,link,is_read,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC,notification_id DESC LIMIT 8');$notificationStmt->execute([$me['user_id']]);$notifications=$notificationStmt->fetchAll();$unreadStmt=$pdo->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$unreadStmt->execute([$me['user_id']]);$unreadNotifications=(int)$unreadStmt->fetchColumn();}catch(PDOException $notificationException){$notificationSetupRequired=true;$notifications=[];$unreadNotifications=0;error_log('Notifications are unavailable. Import upgrade_notifications.sql: '.$notificationException->getMessage());}
} catch (RuntimeException $e) { $error=$e->getMessage(); $tasks=$tasks??[]; $departments=$departments??[]; $roles=$roles??[]; $users=$users??[]; $counts=$counts??['total'=>0,'open_count'=>0,'completed_count'=>0,'approval_count'=>0]; }
catch (PDOException $e) { error_log($e->getMessage()); http_response_code(500); $message = str_contains($e->getMessage(), 'Unknown column') ? 'ฐานข้อมูลยังเป็นโครงสร้างรุ่นเดิม กรุณาสำรองข้อมูลแล้วรัน upgrade_workflow.sql หนึ่งครั้งก่อนใช้งาน' : 'ระบบฐานข้อมูลยังไม่พร้อม กรุณาตรวจสอบการเชื่อมต่อและการติดตั้งตาม README.txt'; exit($message); }

$editTask=null; $editUser=null; $editDepartment=null;
if (isset($_GET['edit_task'])) { foreach($tasks as $t) if((int)$t['task_id']===(int)$_GET['edit_task'] && canEditTask($t,$me,$role)) $editTask=$t; }
if ($isAdmin && isset($_GET['edit_user'])) foreach($users as $u) if((int)$u['user_id']===(int)$_GET['edit_user']) $editUser=$u;
if ($isAdmin && isset($_GET['edit_department'])) { foreach($departments as $d) if((int)$d['department_id']===(int)$_GET['edit_department']) $editDepartment=$d; }
$section=(string)($_GET['section']??'overview');
$pageTitle=match($section){'report'=>'รายงานภาระงาน','tasks'=>'รายการงาน','create'=>'บันทึกภาระงาน','profile'=>'โปรไฟล์ของฉัน','users'=>'จัดการผู้ใช้งาน','departments'=>'จัดการหน่วยงาน',default=>'ระบบบริหารจัดการภาระงาน'};
$staffSummary=[]; $dailyCounts=[];
for($i=13;$i>=0;$i--){$day=date('Y-m-d',strtotime("-$i days"));$dailyCounts[$day]=0;}
foreach($tasks as $task){$name=($isSupervisor?($task['assignee_name']?:$task['creator_name']):$task['creator_name'])??'ไม่ระบุ';if(!isset($staffSummary[$name]))$staffSummary[$name]=['total'=>0,'main'=>0,'special'=>0];$staffSummary[$name]['total']++;$staffSummary[$name][$task['category']==='special'?'special':'main']++;$day=substr((string)$task['created_at'],0,10);if(isset($dailyCounts[$day]))$dailyCounts[$day]++;}
$chartMax=max(1,...array_values($dailyCounts));
?>
