<?php if($isAdmin&&$section==='users'):?><section class="panel"><div class="panel-h"><h2><?=$editUser?'แก้ไขบัญชี':'เพิ่มบัญชีผู้ใช้'?></h2></div><div class="panel-body"><form method="post" action="?section=users" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save_user"><input type="hidden" name="user_id" value="<?=e((string)($editUser['user_id']??0))?>"><div class="field"><label>ชื่อผู้ใช้ *</label><input name="username" required value="<?=e($editUser['username']??'')?>"></div><div class="field"><label>ชื่อแสดงผล *</label><input name="full_name" required value="<?=e($editUser['full_name']??'')?>"></div><div class="field"><label>อีเมล</label><input name="email" type="email" value="<?=e($editUser['email']??'')?>"></div><div class="field"><label>บทบาท</label><select name="role_id"><?php foreach($roles as $r):?><option value="<?=$r['role_id']?>" <?=((int)($editUser['role_id']??0)===(int)$r['role_id'])?'selected':''?>><?=e($r['role_name'])?></option><?php endforeach;?></select></div><div class="field"><label>หน่วยงาน</label><select name="department_id"><option value="0">ไม่ระบุ</option><?php foreach($departments as $d):?><option value="<?=$d['department_id']?>" <?=((int)($editUser['department_id']??0)===(int)$d['department_id'])?'selected':''?>><?=e($d['department_name'])?></option><?php endforeach;?></select></div><div class="field"><label>รหัสผ่าน <?=$editUser?'ใหม่ (เว้นว่างได้)':'เริ่มต้น'?></label><input type="password" name="password" minlength="12" <?=$editUser?'':'required'?>></div><div class="field full"><button class="btn">บันทึก</button><a class="btn light" href="?section=users">ยกเลิก/รายการผู้ใช้</a></div></form></div><div class="table-wrap"><table><thead><tr><th>ผู้ใช้</th><th>บทบาท</th><th>หน่วยงาน</th><th>สถานะ</th><th></th></tr></thead><tbody><?php if(!$users):?><tr><td colspan="5" class="empty"><span class="empty-state-title">ยังไม่มีบัญชีผู้ใช้</span>เพิ่มบัญชีจากแบบฟอร์มด้านบน</td></tr><?php else:foreach($users as $u):?><tr><td><?=e($u['full_name'])?><br><small><?=e($u['username'])?></small></td><td><?=e($roleLabels[$u['role_code']]??$u['role_code'])?></td><td><?=e($u['department_name']??'—')?></td><td><?=e($u['status'])?></td><td><a class="btn light tiny" href="?section=users&amp;edit_user=<?=$u['user_id']?>">แก้ไข</a><form class="inline" method="post"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><button class="btn tiny"><?=$u['status']==='active'?'ปิดใช้':'เปิดใช้'?></button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif;?>
<?php if($isAdmin&&$section==='departments'):?><section class="panel"><div class="panel-h"><h2>จัดการหน่วยงาน</h2></div><div class="panel-body"><form method="post" action="?section=departments" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save_department"><input type="hidden" name="department_id" value="<?=e((string)($editDepartment['department_id']??0))?>"><div class="field"><label>รหัสหน่วยงาน</label><input name="department_code" maxlength="30" value="<?=e($editDepartment['department_code']??'')?>" placeholder="เช่น SCI, IT"></div><div class="field"><label>ชื่อหน่วยงาน *</label><input name="department_name" required maxlength="180" value="<?=e($editDepartment['department_name']??'')?>"></div><div class="field"><button class="btn"><?=$editDepartment?'บันทึกการแก้ไข':'เพิ่มหน่วยงาน'?></button><?php if($editDepartment):?> <a class="btn light" href="?section=departments">ยกเลิก</a><?php endif;?></div></form></div><div class="table-wrap"><table><thead><tr><th>รหัส</th><th>หน่วยงาน</th><th>จำนวนบัญชี</th><th>จัดการ</th></tr></thead><tbody><?php if(!$departments):?><tr><td colspan="4" class="empty"><span class="empty-state-title">ยังไม่มีหน่วยงาน</span>เพิ่มหน่วยงานจากแบบฟอร์มด้านบน</td></tr><?php else:foreach($departments as $d):$dc=$pdo->prepare('SELECT COUNT(*) FROM users WHERE department_id=?');$dc->execute([$d['department_id']]);?><tr><td><?=e($d['department_code']??'—')?></td><td><?=e($d['department_name'])?></td><td><?=$dc->fetchColumn()?></td><td><a class="btn light tiny" href="?section=departments&amp;edit_department=<?=$d['department_id']?>">แก้ไข</a></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif;?>
<?php endif; ?>
<p class="doc-hint" style="text-align:center;margin:18px">ระบบบริหารจัดการภาระงาน · มหาวิทยาลัยนเรศวร</p></div></main></div><script>document.querySelectorAll('form').forEach(f=>{f.addEventListener('submit',()=>{const b=f.querySelector('button[type=submit],button:not([type])');if(b&&f.querySelector('[name=action][value=save_task]')){b.disabled=true;b.textContent='กำลังบันทึก…'}})});document.querySelectorAll('.date-presets button').forEach(b=>b.addEventListener('click',()=>{const form=b.closest('form'),to=form.querySelector('[name=to]'),from=form.querySelector('[name=from]'),end=new Date(),start=new Date(end);start.setDate(start.getDate()-(Number(b.dataset.days)-1));const localDate=d=>{const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};from.value=localDate(start);to.value=localDate(end);form.requestSubmit()}));const successToast=document.querySelector('.toast.ok');if(successToast)setTimeout(()=>{successToast.style.opacity='0';successToast.style.transform='translateY(-7px)';setTimeout(()=>successToast.remove(),220)},4500);document.querySelectorAll('.profile-edit-form').forEach(f=>f.addEventListener('submit',e=>{if(!confirm('ยืนยันการบันทึกข้อมูลโปรไฟล์หรือไม่?'))e.preventDefault()}));document.querySelectorAll('.password-change-form').forEach(f=>f.addEventListener('submit',e=>{const a=f.querySelector('[name=new_password]'),b=f.querySelector('[name=confirm_password]');if(a.value!==b.value){e.preventDefault();b.setCustomValidity('ยืนยันรหัสผ่านไม่ตรงกัน');b.reportValidity()}else{b.setCustomValidity('');if(!confirm('ยืนยันการเปลี่ยนรหัสผ่านหรือไม่?'))e.preventDefault()}}));document.querySelectorAll('.password-change-form [name=confirm_password]').forEach(i=>i.addEventListener('input',()=>i.setCustomValidity('')));document.querySelectorAll('.status-form button,.profile form button').forEach(b=>b.addEventListener('click',e=>{const f=b.closest('form');if(f?.querySelector('[name=action][value=change_status]')&&!confirm('ยืนยันการเปลี่ยนสถานะงานหรือไม่?'))e.preventDefault()}));</script></body></html>
